<template>
  <div class="address">
    <div class="header">
      <router-link class="city" to="/cityList"><i class="icon iconfont">&#xe873;</i>{{city.area_name}}</router-link>
      <div class="input-box">
        <i class="icon iconfont">&#xe61a;</i>
        <input type="text" placeholder="请输入收货地址" v-model="searchKey" @input="searchInput">
        <i class="icon iconfont" v-show="searchKey" @click="clearInput">&#xe61f;</i>
      </div>
    </div>
    <div class="list">
      <div>
        <div class="item current-address" v-show="nowAddress" @click="selectNowAddress">
          <span>{{nowAddress}}</span>
          <span class="btn main-color-font" @click.stop="reLocation"><i class="icon iconfont">&#xe643;</i>刷新</span>
        </div>
        <div class="item" v-for="(item, index) in list" :key="index" @click="selectAddress(item)">{{item.address_name}}（{{item.address}}）</div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'Address',
  data () {
    return {
      list: [],
      searchKey: '',
      city: '',
      nowAddress: '',
      searchTimer: '',
      lng: '',
      lat: ''
    }
  },
  created () {
    this.city = this.$global.city
    // 获取定位信息
    if (this.$util.checkWeixin() && this.$util.checkAndroid()) {
      this.$util.getWxconfig(this.getLocation)
    } else {
      this.getLocation()
    }
    window.getAddressBack = this.getAddressBack.bind(this)
  },
  methods: {
    getLocation () {
      // 获取定位信息
      this.$util.getLocation(this.getLocationOk)
    },
    selectNowAddress () {
      this.$global.address = {
        lng: this.lng,
        lat: this.lat,
        address_name: this.nowAddress
      }
      this.$router.go(-1)
    },
    selectAddress (item) {
      this.$global.address = item
      this.$router.go(-1)
    },
    searchInput () {
      let _this = this
      if (this.searchTimer) {
        clearTimeout(this.searchTimer)
        this.searchTimer = ''
      }
      this.searchTimer = setTimeout(function () {
        if (_this.searchKey) {
          _this.getAddress()
        } else {
          _this.list = []
        }
      }, 700)
    },
    clearInput () {
      this.searchKey = ''
      this.list = []
    },
    async getAddress () {
      let res = await this.$api.searchAddress({ now_city: this.city.area_id, query: this.searchKey, area_name: this.city.area_name })
      if (!res) return
      this.list = res
    },
    // 刷新定位
    reLocation () {
      this.$util.getLocation(this.getLocationOk)
    },
    // 定位成功的回调
    getLocationOk (res) {
      if (res) {
        this.lng = res.lng
        this.lat = res.lat
        this.$util.getAdressDetail(this.lng, this.lat, 'getAddressBack')
      }
    },
    getAddressBack (obj) {
      this.nowAddress = obj.result.formatted_address + obj.result.sematic_description
      let mapObject = document.getElementById('baiduMap')
      if (mapObject != null) {
        mapObject.parentNode.removeChild(mapObject)
      }
    }
  }
}
</script>

<style lang="stylus" scoped>
.address
  background #fff
  .header
    height 50px
    padding 10px 0
    box-sizing border-box
    flexbox()
    align-items center
    .city
      padding 10px 15px
      color #999
      max-width 100px
      ellipsis(1)
      .icon
        padding-right 5px
        vertical-align middle
    .input-box
      flex-grow 1
      background #f8f8f8
      margin-right 15px
      border-radius 15px
      padding 0 5px
      flexbox()
      align-items center
      height 100%
      box-sizing border-box
      input
        background transparent
        flex-grow 1
      .icon
        color #bbb
        font-size 14px
        padding 10px
  .list
    height calc(100% - 50px)
    border-top 1PX solid #efefef
    overflow-y auto
    overflow-x hidden
    .item
      font-size 14px
      color #333
      padding 12px 15px
      border-bottom 1PX solid #efefef
      line-height 1.4
      &:last-child
        border-bottom none
    .current-address
      flexbox()
      justify-content space-between
      align-items center
      padding 0 0 0 15px
      .btn
        color $color-main
        padding 12px 15px
        .icon
          vertical-align middle
</style>
